    "correctIndex": 0,
    "explanation": "1. CONCEPT & PRINCIPLE:\nOptical isomerism and absence of plane of symmetry in octahedral chelate complexes.\n\n2. GIVEN INFORMATION / DATA:\n$[Co(en)_2Cl_2]^+$ isomers and planar/non-chelate complexes.\n\n3. FORMULA / EQUATION:\nChirality condition: Molecule and its mirror image are non-superimposable (lacks center/plane of inversion $\\sigma, i$).\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. In $cis-[Co(en)_2Cl_2]^+$, the two bidentate ethylenediamine ($en$) rings are positioned mutually perpendicular, and the two $Cl^-$ ligands are adjacent ($90^\\circ$).\n2. It lacks any plane of symmetry ($\\sigma$) or center of inversion ($i$). Its mirror image is non-superimposable, making it chiral and optically active (dextro and laevo forms exist).\n3. In contrast, $trans-[Co(en)_2Cl_2]^+$ has a horizontal plane of symmetry passing through $Co$ and the two $Cl^-$ ligands, making it achiral and optically inactive.\n4. $[Pt(NH_3)_2Cl_2]$ is square planar and has a molecular plane of symmetry, precluding optical activity.\n\n5. FINAL CONCLUSION:\n$\\text{cis}-[\\text{Co}(\\text{en})_2\\text{Cl}_2]^+$\n\n6. OPTION ANALYSIS & COMMON TRAPS:\n$trans-[Co(en)_2Cl_2]^+$ has a plane of symmetry; square planar $[Pt(NH_3)_2Cl_2]$ is achiral.",
